def bis(f, lo, hi, n=200):
    flo = f(lo)
    for _ in range(n):
        m = (lo + hi) / 2
        fm = f(m)
        if (flo <= 0) == (fm <= 0):
            lo, flo = m, fm
        else:
            hi = m
    return (lo + hi) / 2

def skill():
    d = 2
    t = Rational(6*d, 2**d - 1)
    return t * (t * 2**d)

def standard():
    s = Symbol('s', real=True)
    a0 = float(solve(Eq(2**(s + 2) - 2**s, 12), s)[0])
    b0 = a0 + 2
    cc = bis(lambda c: ((c-a0)**2 + (c-2**a0)**2) - ((c-b0)**2 + (c-2**b0)**2), -1000, 1000)
    r2 = (cc - a0)**2 + (cc - 2**a0)**2
    g = lambda x: (x - cc)**2 + (math.log2(x) - cc)**2 - r2
    xs = [10**(-3 + 0.001*k) for k in range(0, 6000)]
    roots = [bis(g, x1, x2) for x1, x2 in zip(xs, xs[1:]) if g(x1)*g(x2) < 0]
    assert len(roots) == 2
    return round(roots[0]*roots[1])

def unique():
    return [standard()]
